"""Fetch a public web page's readable text so the planner can ground plans in it.

The planner agent calls :func:`fetch_website_text` as a tool when the user's
prompt references a URL. This module is deliberately dependency-free beyond
``httpx``: HTML-to-text extraction uses only the stdlib ``html.parser``.
"""

from __future__ import annotations

import asyncio
import ipaddress
import socket
from html.parser import HTMLParser
from urllib.parse import urlparse

import httpx
import structlog

structlogger = structlog.get_logger()

_ALLOWED_SCHEMES = {"http", "https"}
_MAX_REDIRECTS = 3
_FETCH_TIMEOUT_SECONDS = 10.0
_MAX_BODY_BYTES = 500_000
_MAX_TEXT_CHARS = 20_000
_TRUNCATION_NOTE = "\n\n[content truncated]"
_HTML_CONTENT_TYPES = ("text/html", "application/xhtml+xml")
_TEXT_CONTENT_TYPES = ("text/plain",)
_SKIPPED_TAGS = {"script", "style", "noscript", "head"}


class _ReadableTextExtractor(HTMLParser):
    """Collect visible text from HTML, skipping script/style/noscript/head."""

    def __init__(self) -> None:
        super().__init__()
        self._skip_depth = 0
        self._chunks: list[str] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag in _SKIPPED_TAGS:
            self._skip_depth += 1

    def handle_endtag(self, tag: str) -> None:
        if tag in _SKIPPED_TAGS and self._skip_depth > 0:
            self._skip_depth -= 1

    def handle_data(self, data: str) -> None:
        if self._skip_depth == 0 and data.strip():
            self._chunks.append(data)

    def get_text(self) -> str:
        """Return the collected text with whitespace collapsed."""
        return " ".join(" ".join(self._chunks).split())


async def fetch_website_text(url: str) -> str:
    """Fetch ``url`` and return its readable text, capped at roughly 20k chars.

    Redirects are followed manually, up to ``_MAX_REDIRECTS`` hops: the
    scheme and resolved host of each hop are validated before it is
    requested, so a public URL cannot redirect the server into fetching an
    internal address (SSRF via redirect).

    Returns a short "Could not fetch <url>: <reason>" string instead of
    raising on any validation, network, or HTTP failure, so the calling agent
    can react in text rather than crash the run.
    """
    try:
        async with httpx.AsyncClient(
            follow_redirects=False, timeout=_FETCH_TIMEOUT_SECONDS
        ) as client:
            current_url = url
            for _ in range(_MAX_REDIRECTS + 1):
                scheme_error = _validate_scheme(current_url)
                if scheme_error is not None:
                    return scheme_error

                # Validate the hop's resolved host before connecting to it. Known
                # gap: the address _resolve_host checks isn't pinned for the
                # connection httpx then opens, so DNS rebinding between the check
                # and the connect isn't covered.
                host_error = await _reject_unsafe_host(current_url)
                if host_error is not None:
                    return host_error

                async with client.stream("GET", current_url) as response:
                    if response.is_redirect:
                        location = response.headers.get("location")
                        if not location:
                            return (
                                f"Could not fetch {url}: redirect from "
                                f"{current_url} had no Location header"
                            )
                        current_url = str(response.url.join(location))
                        continue

                    response.raise_for_status()
                    content_type = response.headers.get("content-type", "")
                    if not _is_acceptable_content_type(content_type):
                        return (
                            f"Could not fetch {url}: unsupported content type "
                            f"'{content_type or 'unknown'}'"
                        )

                    body, was_truncated = await _read_capped_body(response)
                    break
            else:
                return f"Could not fetch {url}: too many redirects"
    except httpx.HTTPStatusError as exc:
        return f"Could not fetch {url}: HTTP {exc.response.status_code}"
    except httpx.HTTPError as exc:
        return f"Could not fetch {url}: {type(exc).__name__}"

    text = _extract_text(body, content_type)
    text, truncated_for_length = _cap_text(text)

    structlogger.info(
        "agent_plan.web_fetch.fetched",
        # Log only the host, not the full URL: the query string or userinfo
        # can carry tokens or credentials that don't belong in logs.
        host=urlparse(url).hostname,
        body_bytes=len(body),
        body_truncated=was_truncated,
        text_truncated=truncated_for_length,
    )
    return text


def _validate_scheme(url: str) -> str | None:
    """Return an error string if ``url``'s scheme is not http/https."""
    scheme = urlparse(url).scheme.lower()
    if scheme not in _ALLOWED_SCHEMES:
        return f"Could not fetch {url}: unsupported URL scheme '{scheme or 'none'}'"
    return None


async def _reject_unsafe_host(url: str) -> str | None:
    """Return an error string if ``url``'s host resolves to a non-public address."""
    hostname = urlparse(url).hostname
    if not hostname:
        return f"Could not fetch {url}: missing host"
    if hostname.lower() == "localhost":
        return f"Could not fetch {url}: refusing to fetch localhost"

    try:
        addresses = await _resolve_host(hostname)
    except OSError as exc:
        return f"Could not fetch {url}: could not resolve host ({exc})"

    if not addresses:
        return f"Could not fetch {url}: host did not resolve to any address"

    for address in addresses:
        if _is_unsafe_address(address):
            return f"Could not fetch {url}: host resolves to a disallowed address"
    return None


async def _resolve_host(hostname: str) -> list[str]:
    """Resolve ``hostname`` to its IP addresses in a worker thread."""
    loop = asyncio.get_running_loop()
    infos = await loop.run_in_executor(
        None, socket.getaddrinfo, hostname, None, socket.AF_UNSPEC, socket.SOCK_STREAM
    )
    return [str(info[4][0]) for info in infos]


def _is_unsafe_address(address: str) -> bool:
    """Return whether ``address`` is private, loopback, link-local, or reserved."""
    try:
        parsed = ipaddress.ip_address(address)
    except ValueError:
        return True
    return (
        parsed.is_private
        or parsed.is_loopback
        or parsed.is_link_local
        or parsed.is_reserved
        or parsed.is_multicast
        or parsed.is_unspecified
        or (isinstance(parsed, ipaddress.IPv6Address) and parsed.is_site_local)
    )


def _is_acceptable_content_type(content_type: str) -> bool:
    """Return whether ``content_type`` is HTML-like or plain text."""
    media_type = content_type.split(";", 1)[0].strip().lower()
    return media_type in _HTML_CONTENT_TYPES or media_type in _TEXT_CONTENT_TYPES


async def _read_capped_body(response: httpx.Response) -> tuple[str, bool]:
    """Stream ``response``'s body, capping it at ``_MAX_BODY_BYTES``."""
    chunks: list[bytes] = []
    total_bytes = 0
    truncated = False
    async for chunk in response.aiter_bytes():
        remaining = _MAX_BODY_BYTES - total_bytes
        if remaining <= 0:
            truncated = True
            break
        if len(chunk) > remaining:
            chunks.append(chunk[:remaining])
            total_bytes += remaining
            truncated = True
            break
        chunks.append(chunk)
        total_bytes += len(chunk)
    body = b"".join(chunks).decode(response.encoding or "utf-8", errors="replace")
    return body, truncated


def _extract_text(body: str, content_type: str) -> str:
    """Extract readable text from ``body``, stripping HTML markup when present."""
    media_type = content_type.split(";", 1)[0].strip().lower()
    if media_type in _HTML_CONTENT_TYPES:
        extractor = _ReadableTextExtractor()
        extractor.feed(body)
        return extractor.get_text()
    return " ".join(body.split())


def _cap_text(text: str) -> tuple[str, bool]:
    """Cap ``text`` at ``_MAX_TEXT_CHARS``, appending a truncation note if cut."""
    if len(text) <= _MAX_TEXT_CHARS:
        return text, False
    return text[:_MAX_TEXT_CHARS] + _TRUNCATION_NOTE, True
